    public var bpm: Double = 0.0

    public var ticks: Double = 0.0

    public var time: Double = 0.0

    public init(_ bpm: Double, _ ticks: Double, _ time: Double) {
        self.bpm = bpm
        self.ticks = ticks
        self.time = time
    }
}

/**
 * A metronome click of the main song used to align the count-in with the song.
 */
internal final class MidiSequencerMetronomeClick: IRecord {
    public var time: Double = 0.0

    public var counter: Double = 0.0

    public var durationInTicks: Double = 0.0

    public var timeSignatureNumerator: Double = 0.0

    public init(time: Double, counter: Double, durationInTicks: Double, timeSignatureNumerator: Double) {
        self.time = time
        self.counter = counter
        self.durationInTicks = durationInTicks
        self.timeSignatureNumerator = timeSignatureNumerator
    }
}

internal final class MidiSequencerState {
    public var tempoChanges: List<MidiFileSequencerTempoChange> = List<MidiFileSequencerTempoChange>()

    public var tempoChangeIndex: Double = 0.0

    public var syncPoints: List<BackingTrackSyncPoint> = List<BackingTrackSyncPoint>()

    public var firstProgramEventPerChannel: Map<Double, SynthEvent> = Map<Double, SynthEvent>()

    public var firstTimeSignatureNumerator: Double = 0.0

    public var firstTimeSignatureDenominator: Double = 0.0

    public var synthData: List<SynthEvent> = List<SynthEvent>()

    public var metronomeClicks: List<MidiSequencerMetronomeClick> = List<MidiSequencerMetronomeClick>()

    public var division: Double = MidiUtils.QuarterTime

    public var eventIndex: Double = 0.0

    public var currentTime: Double = 0.0

    public var syncPointIndex: Double = 0.0

    public var playbackRange: PlaybackRange? = nil

    public var playbackRangeStartTime: Double = 0.0

    public var playbackRangeEndTime: Double = 0.0

    public var endTick: Double = 0.0

    public var endTime: Double = 0.0

